/**
 * translations.js — All UI text for AksharGyan, organized by language.
 *
 * HOW IT WORKS:
 * - Each language has a short code (en, hi, ta, te, kn, bn, mr).
 * - Inside each code is an object whose keys match "data-i18n" attributes in the HTML.
 * - The applyTranslations() function reads the chosen language, finds every element
 *   with a data-i18n attribute, and swaps its text to the correct translation.
 *
 * TO ADD A NEW LANGUAGE:
 * 1. Pick a short code (e.g., "gu" for Gujarati).
 * 2. Add a new object under that code with ALL the same keys.
 * 3. Add a button/option for it on index.html — no other code changes needed.
 */

