    faqSubtitle: "अक्षरज्ञान और अपनी साक्षरता यात्रा शुरू करने के बारे में वह सब कुछ जो आपको जानना आवश्यक है।",
    faq1Q: "क्या अक्षरज्ञान पूरी तरह से मुफ्त है?",
    faq1A: "हाँ! अक्षरज्ञान भारत भर में वयस्क साक्षरता को बढ़ावा देने के लिए एक निःशुल्क शैक्षिक पहल है। सभी पाठ, हस्तलेखन उपकरण, खेल और एआई अभ्यास मॉड्यूल 100% मुफ्त हैं।",
    faq2Q: "अगर मैंने पहले कभी कंप्यूटर या फोन का उपयोग नहीं किया है तो क्या मैं इसे इस्तेमाल कर सकता हूँ?",
    faq2A: "बिल्कुल। अक्षरज्ञान को बड़े टच बटन, अपनी मातृभाषा में आवाज के निर्देशों और सहज दृश्य संकेतों के साथ डिज़ाइन किया गया है ताकि हर कोई आसानी से सीख सके।",
    faq3Q: "एआई मेरे उच्चारण का मूल्यांकन कैसे करता है?",
    faq3A: "हमारा वाक् पहचान मॉडल आपके माइक्रोफ़ोन के माध्यम से आपकी आवाज सुनता है और बिना किसी झिझक के सहायक, सौम्य प्रतिक्रिया प्रदान करता है।",
    faq4Q: "क्या अक्षरज्ञान धीमे इंटरनेट पर काम करता है?",
    faq4A: "हाँ। अक्षरज्ञान को स्मार्ट ऑफलाइन कैशिंग के साथ प्रोग्रेसिव वेब ऐप (PWA) के रूप में बनाया गया है। बुनियादी अक्षर ट्रेसिंग और अभ्यास बिना इंटरनेट के भी काम करते हैं।",
    faq5Q: "क्या शिक्षक और संस्थाएं इसे कक्षाओं में उपयोग कर सकते हैं?",
