    test1Quote: "பல ஆண்டுகளாக பேருந்து நிலையத்தில் என் கிராமத்திற்கு எந்த பேருந்து செல்கிறது என்று பிறரிடம் கேட்க வேண்டியிருந்தது. அக்ஷர்க்யானில் 3 வாரங்களுக்குப் பிறகு, நானே அனைத்துப் பலகைகளையும் மருந்து அளவுகளையும் படிக்கிறேன்.",
    test1Badge: "✓ பேருந்து பலகைகளைப் படிக்கிறார்",
    test2Quote: "குரல் மதிப்பீடு எனக்கு கூச்சமின்றி தமிழ் எழுத்துக்களைப் பேசவும் படிக்கவும் நம்பிக்கையை அளித்தது. இப்போது நான் இடைத்தரகர்கள் இல்லாமல் என் வங்கிப் பாஸ்புக்கை நிர்வகிக்கிறேன்.",
    test2Badge: "✓ வங்கிக் கையாளுதலில் நம்பிக்கை",
    test3Quote: "திரையில் எழுதுவது தினமும் மாலையில் மராத்தி எழுத்துக்களைப் பயிற்சி செய்ய உதவியது. நேற்று கைரேகை வைப்பதற்குப் பதிலாக ஓய்வூதிய ஆவணத்தில் என் சொந்தக் கையொப்பமிட்டேன்.",
    test3Badge: "✓ சொந்தக் கையொப்பமிடுகிறார்",
    test4Quote: "விளையாட்டுகளும் படிப்புக் குழுக்களும் கற்பதை உற்சாகமாக்கின. எங்கள் குழுவில் தினமும் 10 நிமிடங்கள் பயிற்சி செய்கிறோம். இது என் வாழ்க்கையையே மாற்றியது.",
    test4Badge: "✓ டைமண்ட் லீக்",

    faqBadge: "கேள்விகள் உள்ளதா?",
    faqTitle: "அடிக்கடி கேட்கப்படும் கேள்விகள்",
    faqSubtitle: "அக்ஷர்க்யான் மற்றும் உங்கள் எழுத்தறிவுப் பயணத்தைத் தொடங்குவது பற்றி நீங்கள் தெரிந்து கொள்ள வேண்டிய அனைத்தும்.",
    faq1Q: "அக்ஷர்க்யான் முற்றிலும் இலவசமா?",
    faq1A: "ஆம்! அக்ஷர்க்யான் என்பது இந்தியா முழுவதும் வயதுவந்தோர் எழுத்தறிவை மேம்படுத்துவதற்கான ஒரு இலவசக் கல்வி முயற்சியாகும். அனைத்துப் பாடங்கள், கையெழுத்துக் கருவிகள், விளையாட்டுகள் மற்றும் AI பயிற்சிகள் 100% இலவசம்.",
    faq2Q: "நான் இதற்கு முன் கம்ப்யூட்டர் அல்லது போன் பயன்படுத்தியதில்லை என்றால் இதைப் பயன்படுத்தலாமா?",
    faq2A: "நிச்சயமாக. அக்ஷர்க்யான் பெரிய பொத்தான்கள், தாய்மொழியில் குரல் வழிமுறைகள் மற்றும் எளிய காட்சிக் குறிப்புகளுடன் வடிவமைக்கப்பட்டுள்ளது, எனவே அனைவரும் சிரமமின்றிப் பயன்படுத்தலாம்.",
    faq3Q: "AI எனது உச்சரிப்பை எவ்வாறு மதிப்பிடுகிறது?",
    faq3A: "எங்கள் பேச்சு அங்கீகார மாதிரி உங்கள் மைக்ரோஃபோன் வழியாக நீங்கள் பேசும் வாக்கியத்தைக் கேட்டு மென்மையான, ஆதரவான வழிகாட்டலை வழங்குகிறது.",
    faq4Q: "குறைந்த இணைய வேகத்தில் அக்ஷர்க்யான் செயல்படுமா?",
    faq4A: "ஆம். அக்ஷர்க்யான் ஆஃப்லைன் வசதியுடன் கூடிய PWA ஆக உருவாக்கப்பட்டுள்ளது. அடிப்படை எழுத்துப் பயிற்சிகள் இணையம் இல்லாமலும் செயல்படும்.",
    faq5Q: "ஆசிரியர்களும் தன்னார்வ அமைப்புகளும் இதை வகுப்பறைகளில் பயன்படுத்தலாமா?",
    faq5A: "ஆம்! ஆசிரியர்களும் எழுத்தறிவு தொண்டு நிறுவனங்களும் குழு கற்றல் அமர்வுகளை நடத்தவும் மாணவர்களின் முன்னேற்றத்தைக் கண்காணிக்கவும் ஸ்டடி குரூப்ஸ் மற்றும் அட்மின் டாஷ்போர்டைப் பயன்படுத்தலாம்.",

