    chatBankTurn0Inc: "எச்சரிக்கை: புதிய சாதனத்திலிருந்து உள்நுழைய முயற்சி செய்யப்பட்டது. இது நீங்கள் இல்லையென்றால், உங்கள் கணக்கை உடனடியாகப் பூட்ட பதிலளிக்கவும்.",
    chatBankTurn0Opt0: "ஆம், இது நான் தான்.",
