    chatBankTurn0Opt2: "என் இருப்பு என்ன?",
    chatBankTurn1Inc: "உங்கள் கணக்கு தற்காலிகமாகப் பூட்டப்பட்டுள்ளது. உங்கள் நிதியைப் பாதுகாக்க, உங்கள் தற்போதைய டெபிட் கார்டை நாங்கள் தடுக்க வேண்டுமா?",
    chatBankTurn1Opt0: "ஆம், கார்டைத் தடுக்கவும்.",
    chatBankTurn1Opt1: "இல்லை, செயலில் விடவும்.",
    chatBankTurn1Opt2: "எனக்கு ஒரு பீட்சா அனுப்பவும்.",
    chatBankTurn2Inc: "கார்டு வெற்றிகரமாக தடுக்கப்பட்டது. பதிவு செய்யப்பட்ட முகவரிக்கு மாற்று கார்டை அனுப்புவோம். உறுதிப்படுத்த 'CONFIRM' என பதிலளிக்கவும்.",
