    chatRechargeTurn0Inc: "அன்புள்ள வாடிக்கையாளரே, உங்கள் ப்ரீபெய்ட் திட்டம் இன்று முடிவடைகிறது. திட்டங்களைக் காண '1' அல்லது புறக்கணிக்க '2' என பதிலளிக்கவும்.",
