    test1Quote: "చాలా ఏళ్లుగా బస్టాండ్‌లో మా ఊరికి ఏ బస్సు వెళుతుందో ఇతరులను అడగాల్సి వచ్చేది. అక్షర్‌జ్ఞాన్‌లో 3 వారాల తర్వాత, నేనే రూట్ బోర్డులు మరియు మందుల వివరాలను చదవగలుగుతున్నాను.",
