    test2Quote: "వాయిస్ మూల్యాంకనం నాకు సిగ్గుపడకుండా తమిళ అక్షరాలను మాట్లాడే మరియు చదివే ఆత్మవిశ్వాసాన్ని ఇచ్చింది. ఇప్పుడు నేను మధ్యవర్తులు లేకుండా నా బ్యాంక్ పాస్‌బుక్‌ను నిర్వహిస్తున్నాను.",
    test2Badge: "✓ బ్యాంకింగ్‌లో ఆత్మవిశ్వాసం",
    test3Quote: "స్క్రీన్‌పై రాయడం ద్వారా ప్రతి సాయంత్రం మరాఠీ అక్షరాలను సాధన చేయడానికి సహాయపడింది. నిన్న నేను బొటనవేలు వేయకుండా పెన్షన్ పత్రంపై స్వంత సంతకం చేశాను.",
