    faqBadge: "ప్రశ్నలు ఉన్నాయా?",
    faqTitle: "తరచుగా అడిగే ప్రశ్నలు",
    faqSubtitle: "అక్షర్‌జ్ఞాన్ మరియు మీ అక్షరాస్యత ప్రయాణాన్ని ప్రారంభించడం గురించి మీరు తెలుసుకోవలసినవన్నీ.",
    faq1Q: "అక్షర్‌జ్ఞాన్ పూర్తిగా ఉచితమా?",
    faq1A: "అవును! అక్షర్‌జ్ఞాన్ అనేది భారతదేశవ్యాప్తంగా వయోజన అక్షరాస్యతను పెంపొందించడానికి ఉద్దేశించిన ఒక ఉచిత విద్యా చొరవ. అన్ని పాఠాలు, సాధనాలు, ఆటలు మరియు AI అభ్యాసాలు 100% ఉచితం.",
    faq2Q: "నేను ఇంతకు ముందు కంప్యూటర్ లేదా ఫోన్ ఉపయోగించకపోతే దీన్ని ఉపయోగించవచ్చా?",
    faq2A: "ఖచ్చితంగా. అక్షర్‌జ్ఞాన్ పెద్ద బటన్లు, మాతృభాషలో వాయిస్ సూచనలు మరియు సులభమైన దృశ్య సంకేతాలతో రూపొందించబడింది, తద్వారా ప్రతి ఒక్కరూ సులభంగా నేర్చుకోవచ్చు.",
    faq3Q: "AI నా ఉచ్చారణను ఎలా మూల్యాంకనం చేస్తుంది?",
    faq3A: "మా స్పీచ్ రికగ్నిషన్ మోడల్ మీ మైక్రోఫోన్ ద్వారా మీ వాయిస్‌ని వింటుంది మరియు ఎటువంటి ఒత్తిడి లేకుండా సున్నితమైన అభిప్రాయాన్ని అందిస్తుంది.",
    faq4Q: "తక్కువ ఇంటర్నెట్ వేగంలో అక్షర్‌జ్ఞాన్ పనిచేస్తుందా?",
    faq4A: "అవును. అక్షర్‌జ్ఞాన్ ఆఫ్ లైన్ ఫీచర్‌లతో కూడిన PWAగా రూపొందించబడింది. ప్రాథమిక అక్షర సాధన ఇంటర్నెట్ లేకుండా కూడా పనిచేస్తుంది.",
    faq5Q: "ఉపాధ్యాయులు మరియు స్వచ్ఛంద సంస్థలు దీన్ని తరగతులలో ఉపయోగించవచ్చా?",
    faq5A: "అవును! ఉపాధ్యాయులు మరియు అక్షరాస్యత NGOలు గ్రూప్ లెర్నింగ్ సెషన్లను నిర్వహించడానికి మరియు పురోగతిని పర్యవేక్షించడానికి స్టడీ గ్రూప్‌లను ఉపయోగించవచ్చు.",

