    test1Quote: "ವರ್ಷಗಳಿಂದ ಬಸ್ ನಿಲ್ದಾಣದಲ್ಲಿ ನನ್ನ ಹಳ್ಳಿಗೆ ಯಾವ ಬಸ್ ಹೋಗುತ್ತದೆ ಎಂದು ಇತರರನ್ನು ಕೇಳಬೇಕಿತ್ತು. ಅಕ್ಷರಜ್ಞಾನದಲ್ಲಿ 3 ವಾರಗಳ ನಂತರ, ನಾನೇ ಎಲ್ಲಾ ಬೋರ್ಡ್‌ಗಳನ್ನು ಮತ್ತು ಔಷಧಿ ಪ್ರಮಾಣಗಳನ್ನು ಓದಬಲ್ಲೆ.",
