    faqBadge: "ಪ್ರಶ್ನೆಗಳಿವೆಯೇ?",
    faqTitle: "ಸಾಮಾನ್ಯವಾಗಿ ಕೇಳಲಾಗುವ ಪ್ರಶ್ನೆಗಳು",
    faqSubtitle: "ಅಕ್ಷರಜ್ಞಾನ ಮತ್ತು ನಿಮ್ಮ ಸಾಕ್ಷರತಾ ಪಯಣವನ್ನು ಪ್ರಾರಂಭಿಸುವ ಬಗ್ಗೆ ನೀವು ತಿಳಿದುಕೊಳ್ಳಬೇಕಾದ ಎಲ್ಲವೂ.",
    faq1Q: "ಅಕ್ಷರಜ್ಞಾನ ಸಂಪೂರ್ಣವಾಗಿ ಉಚಿತವೇ?",
    faq1A: "ಹೌದು! ಅಕ್ಷರಜ್ಞಾನವು ಭಾರತದಾದ್ಯಂತ ವಯಸ್ಕರ ಸಾಕ್ಷರತೆಯನ್ನು ಸುಧಾರಿಸಲು ಮೀಸಲಾದ ಉಚಿತ ಶೈಕ್ಷಣಿಕ ಉಪಕ್ರಮವಾಗಿದೆ. ಎಲ್ಲಾ ಪಾಠಗಳು, ಬರವಣಿಗೆ ಉಪಕರಣಗಳು, ಆಟಗಳು ಮತ್ತು AI ಅಭ್ಯಾಸಗಳು 100% ಉಚಿತ.",
    faq2Q: "ನಾನು ಈ ಮೊದಲು ಕಂಪ್ಯೂಟರ್ ಅಥವಾ ಫೋನ್ ಬಳಸದಿದ್ದರೆ ಇದನ್ನು ಬಳಸಬಹುದೇ?",
    faq2A: "ಖಂಡಿತವಾಗಿಯೂ. ಅಕ್ಷರಜ್ಞಾನವನ್ನು ದೊಡ್ಡ ಬಟನ್‌ಗಳು, ಮಾತೃಭಾಷೆಯಲ್ಲಿ ಧ್ವನಿ ಸೂಚನೆಗಳು ಮತ್ತು ಸರಳ ದೃಶ್ಯ ಸಂಕೇತಗಳೊಂದಿಗೆ ವಿನ್ಯಾಸಗೊಳಿಸಲಾಗಿದೆ, ಇದರಿಂದ ಯಾರಾದರೂ ಸುಲಭವಾಗಿ ಕಲಿಯಬಹುದು.",
    faq3Q: "AI ನನ್ನ ಉಚ್ಚಾರಣೆಯನ್ನು ಹೇಗೆ ಮೌಲ್ಯಮಾಪನ ಮಾಡುತ್ತದೆ?",
    faq3A: "ನಮ್ಮ ಧ್ವನಿ ಗುರುತಿಸುವಿಕೆ ಮಾದರಿಯು ನಿಮ್ಮ ಮೈಕ್ರೊಫೋನ್ ಮೂಲಕ ನಿಮ್ಮ ಮಾತನ್ನು ಕೇಳುತ್ತದೆ ಮತ್ತು ಯಾವುದೇ ಒತ್ತಡವಿಲ್ಲದೆ ಸೌಮ್ಯವಾದ ಮಾರ್ಗದರ್ಶನವನ್ನು ನೀಡುತ್ತದೆ.",
    faq4Q: "ಕಡಿಮೆ ಇಂಟರ್ನೆಟ್ ವೇಗದಲ್ಲಿ ಅಕ್ಷರಜ್ಞಾನ ಕೆಲಸ ಮಾಡುತ್ತದೆಯೇ?",
    faq4A: "ಹೌದು. ಅಕ್ಷರಜ್ಞಾನವನ್ನು ಆಫ್‌ಲೈನ್ ವೈಶಿಷ್ಟ್ಯಗಳೊಂದಿಗೆ PWA ಆಗಿ ವಿನ್ಯಾಸಗೊಳಿಸಲಾಗಿದೆ. ಮೂಲ ಅಕ್ಷರ ಅಭ್ಯಾಸಗಳು ಇಂಟರ್ನೆಟ್ ಇಲ್ಲದೆಯೂ ಕಾರ್ಯನಿರ್ವಹಿಸುತ್ತವೆ.",
    faq5Q: "ಶಿಕ್ಷಕರು ಮತ್ತು ಸಂಸ್ಥೆಗಳು ಇದನ್ನು ತರಗತಿಗಳಲ್ಲಿ ಬಳಸಬಹುದೇ?",
