    testSubtitle: "বাস্তবসম্মত সাক্ষরতা কীভাবে তাদের দৈনন্দিন স্বাধীনতা বদলে দিয়েছে তা ভারতজুড়ে তুলে ধরছেন শিক্ষার্থীরা।",
    test1Quote: "বহু বছর ধরে বাস টার্মিনালে আমার গ্রামে কোন বাস যায় তা অন্যদের জিজ্ঞাসা করতে হতো। অক্ষরজ্ঞানে ৩ সপ্তাহ পর, আমি নিজেই সব রুট বোর্ড এবং ওষুধের মাত্রা পড়তে পারি।",
    test1Badge: "✓ বাসের বোর্ড পড়তে পারেন",
    test2Quote: "ভয়েস মূল্যায়ন আমাকে কোনো দ্বিধা ছাড়াই তামিল অক্ষর বলতে এবং পড়ার আত্মবিশ্বাস দিয়েছে। এখন আমি কোনো দালাল ছাড়াই আমার ব্যাংকের পাসবুক পরিচালনা করি।",
    test2Badge: "✓ ব্যাংকিংয়ে আত্মবিশ্বাসী",
