    faq1Q: "অক্ষরজ্ঞান কি সম্পূর্ণ বিনামূল্যে ব্যবহারযোগ্য?",
    faq1A: "হ্যাঁ! অক্ষরজ্ঞান হলো ভারতজুড়ে বয়স্ক সাক্ষরতার উন্নতির জন্য নিবেদিত একটি সম্পূর্ণ বিনামূল্যে শিক্ষামূলক উদ্যোগ। সমস্ত পাঠ, লেখার টুল, গেম এবং এআই অনুশীলন ১০০% ফ্রি।",
    faq2Q: "আমি কি আগে কখনো কম্পিউটার বা ফোন ব্যবহার না করে থাকলে এটি ব্যবহার করতে পারি?",
    faq2A: "অবশ্যই। অক্ষরজ্ঞান বড় টাচ বাটন, মাতৃভাষায় ভয়েস নির্দেশাবলী এবং সহজ ভিজ্যুয়াল সংকেত দিয়ে তৈরি যাতে প্রত্যেকে অনায়াসে শিখতে পারে।",
    faq3Q: "এআই কীভাবে আমার উচ্চারণ মূল্যায়ন করে?",
    faq3A: "আমাদের স্পিচ রিকগনিশন মডেল আপনার মাইক্রোফোনের মাধ্যমে আপনার কথা শোনে এবং কোনো চাপ ছাড়াই সহায়ক, মৃদু প্রতিক্রিয়া প্রদান করে।",
    faq4Q: "ধীরগতির ইন্টারনেটে কি অক্ষরজ্ঞান কাজ করে?",
    faq4A: "হ্যাঁ। অক্ষরজ্ঞান স্মার্ট অফলাইন ক্যাশিং সহ প্রোগ্রেসিভ ওয়েব অ্যাপ (PWA) হিসেবে তৈরি। মূল অক্ষর ট্রেসিং এবং অনুশীলন ইন্টারনেট ছাড়াও কাজ করে।",
    faq5Q: "শিক্ষক ও স্বেচ্ছাসেবী সংস্থাগুলি কি এটি ক্লাসরুমে ব্যবহার করতে পারে?",
    faq5A: "হ্যাঁ! শিক্ষক এবং সাক্ষরতা এনজিওরা গ্রুপ লার্নিং সেশন পরিচালনা এবং অগ্রগতি ট্র্যাক করতে স্টাডি গ্রুপ এবং অ্যাডমিন ড্যাশবোর্ড ব্যবহার করতে পারেন।",

